<?php
namespace Modules\Ran\Services;use Illuminate\Support\Facades\DB;use Modules\Ran\Entities\{Payment,Sale};use Modules\Ran\Integrations\{CustomerIntegrationService,FinanceIntegrationService};use Modules\Ran\Support\RanContext;
class CustomerPaymentService{public function __construct(private NumberSequenceService $numbers,private CustomerIntegrationService $customers,private FinanceIntegrationService $finance,private AuditService $audit){}public function create(array $d):Payment{return DB::transaction(function()use($d){$sale=!empty($d['sale_id'])?Sale::query()->lockForUpdate()->findOrFail($d['sale_id']):null;$contactId=$sale?->customer_contact_id?:($d['customer_contact_id']??null);if($sale&&!empty($d['customer_contact_id'])&&(int)$d['customer_contact_id']!==(int)$sale->customer_contact_id)throw new \DomainException('Selected invoice does not belong to the selected customer.');if($contactId)$this->customers->find((int)$contactId);$p=Payment::create(array_merge(RanContext::scope(),$d,['customer_contact_id'=>$contactId,'payment_no'=>$this->numbers->next('customer_payment'),'status'=>'posted']));$this->finance->postCustomerPayment($p);if($contactId)$this->customers->credit((int)$contactId,(float)$p->amount,(string)$p->payment_date,"Ran Payment {$p->payment_no}");if($sale){$paid=min((float)$sale->total_amount,(float)$sale->paid_amount+(float)$p->amount);$balance=max(0,(float)$sale->total_amount-$paid);$sale->update(['paid_amount'=>$paid,'balance_amount'=>$balance,'status'=>$balance<=0.0001?'paid':'part_paid']);}$this->audit->record('customer_payment_posted',$p);return $p;});}}
